import React, { useState } from 'react';
import { FiDownload, FiMusic, FiHeadphones, FiBookOpen, FiShoppingBag } from 'react-icons/fi';
import { FaMusic } from 'react-icons/fa';
import QRPayment from './QRPayment';

const Products = () => {
  const [selectedProduct, setSelectedProduct] = useState(null);
  const [showPayment, setShowPayment] = useState(false);

  const products = [
    {
      id: 1,
      name: 'Beginner Guitar Masterclass',
      description: 'Complete video course covering chords, strumming patterns, and your first 10 songs. Includes downloadable practice tracks.',
      price: 499,
      category: 'Course',
      icon: <FiMusic />,
      popular: true,
      features: ['10 HD Video Lessons', 'Chord Charts PDF', 'Practice Tracks', 'Lifetime Access']
    },
    {
      id: 2,
      name: 'Vocal Warmup Pack',
      description: 'Professional vocal warmup tracks and exercises used by Shawn himself. Perfect for daily practice routines.',
      price: 299,
      category: 'Audio Pack',
      icon: <FiHeadphones />,
      features: ['5 Audio Tracks', 'Breathing Exercises Guide', 'Pitch Training Loops', 'Daily Routine Chart']
    },
    {
      id: 3,
      name: 'Worship Rhythm Backing Tracks',
      description: 'Premium worship-style backing tracks in multiple keys. Ideal for practice, performance, and worship sessions.',
      price: 399,
      category: 'Backing Tracks',
      icon: <FaMusic />,
      features: ['20 HQ Tracks', 'Multi-Key Versions', 'BPM Range 70-130', 'Studio Mastered']
    },
    {
      id: 4,
      name: 'Music Theory Essentials E-Book',
      description: 'Comprehensive guide to music theory for the modern musician. From scales to song structure - simplified.',
      price: 199,
      category: 'E-Book',
      icon: <FiBookOpen />,
      features: ['120+ Pages', 'Interactive Examples', 'Quiz Included', 'Printable']
    }
  ];

  const handleBuy = (product) => {
    setSelectedProduct(product);
    setShowPayment(true);
  };

  return (
    <section className="products-section" id="products">
      <div className="container">
        <div className="section-header reveal">
          <span className="section-tag">Digital Products</span>
          <h2 className="section-title">Level Up Your <span className="gradient-text">Musicianship</span></h2>
          <p className="section-subtitle">Download premium learning materials and audio packs</p>
        </div>

        <div className="products-grid">
          {products.map((product, index) => (
            <div className={`product-card reveal ${product.popular ? 'popular' : ''}`} key={product.id}>
              {product.popular && <span className="popular-badge">Most Popular</span>}
              <span className="product-category">{product.category}</span>
              <div className="product-icon">{product.icon}</div>
              <h3>{product.name}</h3>
              <p>{product.description}</p>
              <div className="product-features">
                {product.features.map((feature, i) => (
                  <span key={i}>✓ {feature}</span>
                ))}
              </div>
              <div className="product-footer">
                <span className="product-price">₹{product.price}</span>
                <button className="btn btn-primary btn-sm" onClick={() => handleBuy(product)}>
                  <FiDownload /> Get It
                </button>
              </div>
            </div>
          ))}
        </div>

        {showPayment && selectedProduct && (
          <div className="payment-modal">
            <div className="payment-modal-content">
              <button className="close-btn" onClick={() => setShowPayment(false)}>×</button>
              <h3>Purchase: {selectedProduct.name}</h3>
              <p className="product-price-display">₹{selectedProduct.price}</p>
              <QRPayment 
                productName={selectedProduct.name}
                price={selectedProduct.price}
                compact={true}
              />
            </div>
          </div>
        )}
      </div>
    </section>
  );
};

export default Products;
